# Initialize dashboard for accounts: 120002, 120001, 320002, 320003, 153000
target_accounts = ['120002', '120001', '320002', '320003', '153000']

for account_code in target_accounts:
    account = env['account.account'].search([('code', '=', account_code)], limit=1)
    if account:
        existing = env['cash.flow.dashboard'].search([('account_id', '=', account.id)])
        if not existing:
            env['cash.flow.dashboard'].create({
                'account_id': account.id,
            })
            print(f"Created dashboard record for account {account_code}")
    else:
        print(f"Account {account_code} not found")
